// Purpose: What the update script generated by UpdateScriptBuilder does: the
//          process to wait for, the folders, the files of the user to keep,
//          the services to stop and start again, the restart of the tool.
// -----------------------------------------------------------------------------
using System.Collections.Generic;

namespace LiteSuite
{
    public sealed class UpdateScriptOptions
    {
        /// <summary>Name shown in the script and its log (e.g. "LiteDeploy").</summary>
        public string ApplicationName;
        /// <summary>The running tool: the script waits for it to exit (60 s, then stops it).</summary>
        public int ProcessId;
        /// <summary>Installation folder: the files are copied there.</summary>
        public string ApplicationDirectory;
        /// <summary>Folder of the new files (the folder of the executable in the extracted package).</summary>
        public string SourceDirectory;
        /// <summary>File name of the executable (e.g. "LitePM.exe"), restarted at the end.</summary>
        public string ExecutableName;
        /// <summary>Arguments of the restarted tool; empty: none.</summary>
        public string RestartArguments = "";
        /// <summary>Restart the tool at the end (default).</summary>
        public bool Restart = true;
        /// <summary>
        /// Files of the user kept when they already exist: PowerShell -like patterns, relative to the
        /// installation folder ("adcache.xml", "*.local.*", "config\*.xml"). '*' also matches '\'.
        /// </summary>
        public List<string> PreservePatterns = new List<string>();
        /// <summary>Services stopped before the copy, started again after it if they were running.</summary>
        public List<string> ServiceNames = new List<string>();
        /// <summary>Copy in an elevated PowerShell (UAC); the tool is restarted without elevation.</summary>
        public bool Elevate;
        /// <summary>Work folder of this update (package, script, backup), deleted at the end.</summary>
        public string WorkDirectory;
        /// <summary>Log of the script (kept after the update).</summary>
        public string LogPath;
    }
}
